/* ============================================
   EMPTY STATE COMPONENT
   Placeholder for lists, tables, and searches
   that have nothing to show
   ============================================ */

.ds-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: var(--gap-400); /* 16px */
  padding: var(--padding-1000); /* 32px */
  width: 100%;
  /* width: 100% plus own padding — border-box locally (as ContactCard,
     Checkbox, Composer, SelectionCard and Textarea do), so a consumer
     without a global reset doesn't get a horizontal scrollbar wherever
     this is embedded. */
  box-sizing: border-box;
}

/* ============================================
   ICON
   ============================================ */

.ds-empty-state__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: var(--radius-pill);
  background-color: var(--color-bg-container-primary);
  color: var(--color-icon-primary);
  flex-shrink: 0;
}

.ds-empty-state__icon .material-symbols-rounded {
  --icon-size: var(--icon-size-600);
}

/* ============================================
   CONTENT
   ============================================ */

.ds-empty-state__content {
  display: flex;
  flex-direction: column;
  gap: var(--gap-100); /* 4px */
  max-width: 420px;
}

.ds-empty-state__title {
  font-family: var(--font-title-body-family);
  font-size: var(--font-title-body-size);
  font-weight: var(--font-title-body-weight);
  line-height: var(--font-title-body-line-height);
  letter-spacing: var(--font-title-body-letter-spacing);
  color: var(--color-text-primary);
  margin: 0;
}

.ds-empty-state__description {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
  margin: 0;
}

/* ============================================
   ACTION
   ============================================ */

.ds-empty-state__action {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: var(--gap-200); /* 8px */
}

/* ============================================
   VARIANT — BORDERED
   Dashed container for use inside cards/tables
   ============================================ */

.ds-empty-state--bordered {
  border: var(--border-025) dashed var(--color-bg-container-border);
  border-radius: var(--radius-300); /* 12px */
}

/* ============================================
   SIZE — COMPACT
   ============================================ */

.ds-empty-state--compact {
  gap: var(--gap-200); /* 8px */
  padding: var(--padding-500); /* 20px */
}

.ds-empty-state--compact .ds-empty-state__icon {
  width: 36px;
  height: 36px;
}

.ds-empty-state--compact .ds-empty-state__icon .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
}

.ds-empty-state--compact .ds-empty-state__title {
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
}

/* Icons take the colour of the text around them. Explicit, not just
   inherited by default: a consumer stylesheet that sets a colour on
   .material-symbols-rounded itself (a common global default) would
   otherwise override inheritance and detach the icon from the state
   colours this component sets on its parents.

   The action slot is carved out: it holds consumer Buttons, which colour
   their icon on the icon element itself, through single-class selectors
   this two-class rule outranks. Left blanket, a primary Button in an
   empty state painted its icon the page's text colour instead of the
   on-action one — a near-black glyph on a filled button. :where() keeps
   the selector at its original specificity. */
.ds-empty-state .material-symbols-rounded:not(:where(.ds-empty-state__action *)) {
  color: inherit;
}

import React from 'react';
import './EmptyState.css';
import '../../fonts/material-symbols.css';

export interface EmptyStateProps {
  /** Material Symbol icon name, or a custom element (e.g. an illustration) */
  icon?: string | React.ReactNode;
  /** Short headline describing the empty condition */
  title: string;
  /** Supporting copy — say what to do next, not just what is missing */
  description?: string;
  /** Action slot — typically one primary Button, optionally a secondary */
  action?: React.ReactNode;
  /** Component size */
  size?: 'default' | 'compact';
  /**
   * Visual treatment. `plain` sits directly on the page; `bordered` draws a
   * dashed container, which reads better inside a card, table, or panel.
   */
  variant?: 'plain' | 'bordered';
  /** Additional CSS classes */
  className?: string;
}

/**
 * EmptyState component — the placeholder shown when a list, table, search,
 * or dashboard has nothing to display. Pairs an icon with a headline,
 * supporting copy, and an optional action so the blank space still tells
 * the user what to do next.
 */
export const EmptyState = ({
  icon,
  title,
  description,
  action,
  size = 'default',
  variant = 'plain',
  className = '',
}: EmptyStateProps) => {
  const baseClass = 'ds-empty-state';

  const classes = [
    baseClass,
    `${baseClass}--${variant}`,
    size === 'compact' ? `${baseClass}--compact` : '',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <div className={classes}>
      {icon && (
        <div className={`${baseClass}__icon`} aria-hidden="true">
          {typeof icon === 'string' ? (
            <span className="material-symbols-rounded">{icon}</span>
          ) : (
            icon
          )}
        </div>
      )}

      <div className={`${baseClass}__content`}>
        <p className={`${baseClass}__title`}>{title}</p>
        {description && <p className={`${baseClass}__description`}>{description}</p>}
      </div>

      {action && <div className={`${baseClass}__action`}>{action}</div>}
    </div>
  );
};
